#!/usr/bin/env bash
# Update the Sphinx Stack files in docs/ to a canonical/sphinx-stack release.
# Usage: .github/scripts/update-sphinx-stack.sh [<TAG>]
#
# Without a tag, uses the latest release. Copies docs/_dev/, records the tag in
# docs/_dev/version, and regenerates docs/requirements.txt from the release's
# requirements plus docs/requirements.in. docs/Makefile carries Workshop's
# lychee link check, so the script only prints the upstream Makefile changes
# for you to merge by hand.

set -euo pipefail

repo=canonical/sphinx-stack
docs_dir=$(git rev-parse --show-toplevel)/docs
tag=${1:-$(gh release view -R "$repo" --json tagName --jq .tagName)}
previous=$(tr -d '[:space:]' < "$docs_dir/_dev/version")

tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT

git clone --quiet --depth 1 --branch "$tag" "https://github.com/$repo.git" "$tmp/sphinx-stack" 2>/dev/null
upstream=$tmp/sphinx-stack/docs

# Overwrite the stack-managed files; untracked caches in docs/_dev/ stay put.
cp -a "$upstream/_dev/." "$docs_dir/_dev/"
git -C "$docs_dir" ls-files _dev | while read -r file; do
    [ -e "$upstream/$file" ] || echo "Removed upstream, delete by hand: docs/$file"
done

# A release's own version file can lag its tag.
printf '%s\n' "$tag" > "$docs_dir/_dev/version"

{
    printf '# Generated by .github/scripts/update-sphinx-stack.sh. Do not edit.\n'
    printf '# Sources: %s %s docs/requirements.txt, docs/requirements.in\n\n' "$repo" "$tag"
    cat "$upstream/requirements.txt"
    printf '\n'
    cat "$docs_dir/requirements.in"
} > "$docs_dir/requirements.txt"

echo "Updated docs/_dev/ and docs/requirements.txt to Sphinx Stack $tag."

if git -C "$tmp/sphinx-stack" fetch --quiet --depth 1 origin tag "$previous" 2>/dev/null; then
    changes=$(git -C "$tmp/sphinx-stack" diff "$previous" "$tag" -- docs/Makefile)
    if [ -z "$changes" ]; then
        echo "No upstream Makefile changes between $previous and $tag."
    else
        echo "Merge these upstream Makefile changes ($previous to $tag) into docs/Makefile:"
        echo "$changes"
    fi
else
    echo "Can't fetch tag $previous; compare docs/Makefile with the $tag Makefile by hand:"
    diff -u --label docs/Makefile --label "$repo $tag docs/Makefile" \
        "$docs_dir/Makefile" "$upstream/Makefile" || true
fi
